<script setup>import AdminShell from '../../components/AdminShell.vue';import StatusBadge from '../../components/StatusBadge.vue';import {assets,spareParts} from '../../api/mock';</script>
<template><AdminShell><template #title>资产台账</template><div class="heading"><div><p>ASSET MASTER DATA</p><h1>资产台账</h1><span>统一管理设备档案、位置、责任人、价值与全生命周期履历</span></div><div><button class="btn ghost">导入台账</button><button class="btn primary">＋ 新建资产</button></div></div>
 <section class="asset-summary"><div><small>资产分类</small><b>生产设备 / 动力设备 / 物流设备</b></div><div><small>当前组织</small><b>知华智造一号工厂</b></div><div><small>本月新增</small><b>18 台 / 套</b></div><div><small>盘点进度</small><b>82.6%</b></div></section>
 <section class="panel"><div class="toolbar"><div class="tabs"><button class="active">全部资产 <b>1,248</b></button><button>重点设备 <b>86</b></button><button>需关注 <b>74</b></button><button>停机检修 <b>28</b></button></div><div><label>⌕ <input placeholder="编码 / 名称 / 位置"/></label><button>筛选 ⌄</button></div></div><table class="asset-table"><thead><tr><th>资产编码 / 名称</th><th>分类</th><th>所在位置</th><th>责任人</th><th>健康状态</th><th>运行状态</th><th>利用率</th><th>资产原值</th><th></th></tr></thead><tbody><tr v-for="a in assets" :key="a.code"><td><b>{{a.code}}</b><small>{{a.name}}</small></td><td><span class="model-chip">{{a.category}}</span></td><td>{{a.location}}</td><td><span class="avatar">{{a.custodian[0]}}</span>{{a.custodian}}</td><td><StatusBadge :value="a.health"/></td><td><StatusBadge :value="a.status"/></td><td><div class="util"><i><em :style="{width:a.utilization+'%'}"></em></i><b>{{a.utilization}}%</b></div></td><td>¥ {{a.value}}</td><td>•••</td></tr></tbody></table><div class="table-note"><span>显示 1–4，共 1,248 条资产</span><div><button>‹</button><button class="active">1</button><button>2</button><button>3</button><button>›</button></div></div></section>
 <section class="panel spare-preview"><header><div><h2>低库存备件提醒</h2><p>低于安全库存的关键备件</p></div><button>进入备件库存 →</button></header><div><article v-for="p in spareParts.filter(i=>i.stock<i.safety)" :key="p.code"><span>!</span><div><b>{{p.name}}</b><small>{{p.code}} · {{p.spec}} · {{p.warehouse}}</small></div><strong>{{p.stock}}<small>/ {{p.safety}} {{p.unit}}</small></strong><button>创建补货申请</button></article></div></section>
 </AdminShell></template>
